public:
    ListNode* swapPairs(ListNode* head) {
        // 哑节点 + 三指针：prev -> a -> b，交换 a、b 后移动 prev
        ListNode dummy(0);
        dummy.next = head;
        ListNode* prev = &dummy;
        while (prev->next && prev->next->next) {
            ListNode* a = prev->next;
            ListNode* b = a->next;
            a->next = b->next;
            b->next = a;
            prev->next = b;
            prev = a;
        }
        return dummy.next;
    }
};

