class Solution {
public:
    int detectCycle(ListNode* head) {
        // 快慢指针相遇后，从头再同步走，相遇点即环入口
        ListNode* slow = head;
        ListNode* fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
            if (slow == fast) {
                ListNode* p = head;
                while (p != slow) {
                    p = p->next;
                    slow = slow->next;
                }
                return p->val;
            }
        }
        return -1;
    }
};

